import { fontFamily, themeColors } from '../libreria/MainLibrary.tsx'
import { sx } from '../utils/mui.utils.ts'

export default function useCallToActionSx() {
  return {
    BoxProgettiButtons: sx({
      borderRadius: '15px',
      border: `0.5vh solid ${themeColors.border}`,
      minWidth: { xs: '350px', md: '488px' },
      minHeight: { xs: '70px', md: '100px' },
      width: { xs: '350px', md: '488px' },
      height: 'auto',
      maxWidth: { xs: '350px', md: '488px' },
      maxHeight: 'auto'
    }),

    WebSites: sx({
      width: { xs: '40%', md: '20%' },
      height: { xs: '40%', md: '20%' },
      borderRadius: '15px',
      border: `0.5vh solid ${themeColors.border}`
    }),

    FullPage: sx({
      display: 'flex',
      flexDirection: 'column',
      background: themeColors.background,
      alignItems: 'center',
      justifyContent: 'flex-start',
      gap: 2,
      width: '100%',
      minHeight: '100vh'
    }),

    TextStyle: sx({
      color: themeColors.textSecondary,
      fontSize: 'clamp(16px, 2vw, 48px)',
      fontFamily: fontFamily
    })
  }
}
