import { Box, Typography } from '@mui/material'
import {
  fontFamily,
  sottotitolo,
  themeColors
} from '../libreria/MainLibrary.tsx'

import useProjectsPageSx from '../style/useProjectsPageSx.ts'
import ButtonBlue from '../widget/ButtonBlue.tsx'

export default function ProjectsPage() {
  const sx = useProjectsPageSx()
  return (
    <Box sx={{ display: 'flex', flexDirection: 'column', minHeight: '100vh' }}>
      <Box
        sx={{
          width: '100%',
          height: '80px',
          background: themeColors.background,
          borderBottom: `1.5px solid ${themeColors.border}`,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          pr: 2,
          pl: 2
        }}
      >
        <Typography
          sx={{
            fontSize: {
              xs: '30px',
              md: '50px'
            },
            lineHeight: 1.2,
            fontWeight: 700,
            color: themeColors.primary,
            fontFamily: fontFamily.mainText
          }}
        >
          I MIEI PROGETTI
        </Typography>

        <ButtonBlue
          children="Homepage"
          backgroundColor="transparent"
          border={true}
          textColor={themeColors.text}
          hoverColor={themeColors.card}
          to="/"
          widthXs="150px"
        />
      </Box>
      <Box sx={sx.FullPage}>
        <Box
          sx={{
            display: 'flex',
            flexDirection: 'column',
            gap: 5,
            mt: '5vh',
            alignItems: 'center'
          }}
        >
          <Typography sx={sottotitolo}>
            COMPONENTI CREATI SU RICHIESTA
          </Typography>
          <Box
            component="img"
            src="/alphaproject/svg/ButtonRedImg.png"
            sx={sx.BoxProgettiButtons}
          />
          <Box
            component="img"
            src="/alphaproject/svg/ButtonYellowImg.png"
            sx={sx.BoxProgettiButtons}
          />
          <Box
            component="img"
            src="/alphaproject/svg/TaskGNC.png"
            sx={sx.BoxProgettiButtons}
          />
        </Box>
        <Box
          sx={{
            display: 'flex',
            flexDirection: 'column',
            gap: 5,
            mt: '5vh',
            alignItems: 'center'
          }}
        >
          <Typography sx={sottotitolo}>WEBSITES CREATI SU RICHIESTA</Typography>
          <Box
            component="img"
            src="/alphaproject/svg/GreenWebsite.png"
            sx={sx.WebSites}
          />
          <Box
            component="img"
            src="/alphaproject/svg/FoodWebsite.png"
            sx={sx.WebSites}
          />
          <Box
            component="img"
            src="/alphaproject/svg/SpaceWebsite.png"
            sx={sx.WebSites}
          />
        </Box>
      </Box>
    </Box>
  )
}
